<script lang="ts">import '../app.css';import {page} from '$app/state';import {currentIdToken,discard,establish,session} from '$lib/session.svelte';import {logoutUrl} from '$lib/oidc';let{children}=$props();const publicRoute=$derived(page.url.pathname.startsWith('/oauth/')||page.url.pathname==='/signed-out'||page.url.pathname.startsWith('/invitations/'));let started=false;$effect(()=>{if(!publicRoute&&!started){started=true;void establish(page.url.pathname+page.url.search)}});function leave(){const url=logoutUrl(currentIdToken());discard();location.assign(url)}</script>
{#if publicRoute}{@render children()}{:else if session.ready&&session.me}<div class="shell"><header class="top"><a class="brand" href="/">MakersBrain</a><div class="actions"><span class="muted">{session.me.email}</span><button class="secondary" onclick={leave}>Sign out</button></div></header>{@render children()}</div>{:else if session.ready}<main class="shell"><p class="error">{session.error||'This account is not linked to MakersBrain.'}</p></main>{:else}<main class="shell"><p>Opening your workshop…</p></main>{/if}
